mapper.select:
SELECT id, tenant_id AS tenantId, site_id AS siteId
FROM equipment
WHERE tenant_id = #{tenantId} AND id = #{equipmentId}

SELECT id, tenant_id AS tenantId, enabled
FROM sites
WHERE tenant_id = #{tenantId} AND id = #{siteId}

mapper.sql:
SELECT p.id, p.tenant_id, p.site_id, p.equipment_id, p.name, p.plan_type, p.content, p.cycle_days, p.next_due_date, p.assignee_user_id, p.enabled, p.created_by, p.created_at, p.updated_at, e.asset_code AS equipment_asset_code, e.name AS equipment_name, u.display_name AS assignee_name FROM maintenance_plans p LEFT JOIN equipment e ON e.tenant_id = p.tenant_id AND e.id = p.equipment_id LEFT JOIN tenant_memberships tm ON tm.tenant_id = p.tenant_id AND tm.user_id = p.assignee_user_id LEFT JOIN users u ON u.id = tm.user_id WHERE p.tenant_id = #{tenantId}
AND p.name LIKE CONCAT('%', #{query.keyword}, '%')
AND p.equipment_id = #{query.equipmentId}
AND p.plan_type = #{query.planType,javaType=com.equipops.domain.enums.MaintenancePlanType,typeHandler=org.apache.ibatis.type.EnumTypeHandler}
AND p.enabled = #{query.enabled}

mapper.select:
SELECT enabled FROM maintenance_plans
WHERE tenant_id = #{tenantId} AND id = #{id}
FOR UPDATE

mapper.update:
UPDATE maintenance_plans
SET name = #{request.name}, equipment_id = #{request.equipmentId}, site_id = #{siteId},
    plan_type = #{request.planType,javaType=com.equipops.domain.enums.MaintenancePlanType,typeHandler=org.apache.ibatis.type.EnumTypeHandler},
    content = #{request.content}, cycle_days = #{request.cycleDays},
    next_due_date = #{request.nextDueDate}, assignee_user_id = #{request.assigneeUserId}
WHERE tenant_id = #{tenantId} AND id = #{id}

